export const PECAS_RECIFES = Object.keys(PECAS)                          ;

export function pintarPecaRecifes(pintar             , nome             , x        , y        )       {
  const [topo, linhas] = PECAS[nome];
  linhas.forEach((linha, j) => {
    // Percorre faixas da mesma cor, preservando os recortes transparentes.
    for (let i = 0; i < linha.length;) {
      const indice = linha[i];
      let fim = i + 1;
      while (linha[fim] === indice) fim++;
      const cor = PALETA[indice];
      if (cor) pintar(cor, x + i, y + topo + j, fim - i, 1);
      i = fim;
    }
  });
}
